import math

def count_divisors(n):
    """Calculates the number of positive divisors of n, tau(n)."""
    count = 0
    for i in range(1, int(math.sqrt(n)) + 1):
        if n % i == 0:
            if i * i == n:
                count += 1
            else:
                count += 2
    return count

results = []
for k in range(1, 13):
    N = 2 * (k**3)
    tau_N = count_divisors(N)
    target = 2 * k
    match = tau_N == target
    results.append({
        'k': k,
        '2k': target,
        'tau(2k^3)': tau_N,
        'match': match
    })

print("k | 2k | tau(2k^3) | Match")
print("-" * 35)
for r in results:
    print(f"{r['k']:2} | {r['2k']:2} | {r['tau(2k^3)']:9} | {r['match']}")
